begin;

create temporary table market_replay_instrument_seed (
    game_date date not null,
    player_id varchar(64) not null,
    actual_net_points_micros bigint not null,
    expected_net_points_micros bigint not null,
    dividend_cents bigint not null,
    actual_minutes_micros bigint not null,
    projected_minutes_micros bigint,
    qualifies_for_instruments boolean not null,
    primary key (game_date, player_id)
) on commit drop;

;

do $$
begin
    if exists (
        select 1
        from public.market_replay_events as event
        join market_replay_instrument_seed as seed
          using (game_date, player_id)
        where event.actual_net_points_micros <> seed.actual_net_points_micros
           or event.expected_net_points_micros <> seed.expected_net_points_micros
           or event.dividend_cents <> seed.dividend_cents
    ) then
        raise exception 'canonical replay event conflict';
    end if;
end
$$;

    game_date, player_id, actual_net_points_micros,
    expected_net_points_micros, dividend_cents,
    actual_minutes_micros, projected_minutes_micros,
    qualifies_for_instruments
)
select game_date, player_id, actual_net_points_micros,
       expected_net_points_micros, dividend_cents,
       actual_minutes_micros, projected_minutes_micros,
       qualifies_for_instruments
from market_replay_instrument_seed
on conflict (game_date, player_id) do update
set actual_minutes_micros = excluded.actual_minutes_micros,
    projected_minutes_micros = excluded.projected_minutes_micros,
    qualifies_for_instruments = excluded.qualifies_for_instruments;

commit;
